<script setup>
import { ref, onMounted, onUnmounted } from 'vue'
const props = defineProps({task:{type:Object,required:true}}); const emit=defineEmits(['remove','check','priority','due-date']); const elapsed=ref(''); let timer
function updateTime(){const minutes=Math.max(0,Math.floor((Date.now()-props.task.time)/60000));elapsed.value=minutes>=1440?`${Math.floor(minutes/1440)} días`:minutes>=60?`${Math.floor(minutes/60)} horas`:`${minutes} minutos`}
function editDue(event){emit('due-date',props.task.id,event.target.value)}
onMounted(()=>{updateTime();timer=setInterval(updateTime,30000)});onUnmounted(()=>clearInterval(timer))
</script>
<template><article class="task-card" :class="{completed:task.done}"><button class="check" :class="{active:task.done}" @click="emit('check',task.id,!task.done)">{{task.done?'✓':''}}</button><div class="task-main"><h3>{{task.name}}</h3><p>Creado hace {{elapsed}}</p><label class="due-date"><span>Entrega</span><input type="datetime-local" :value="task.dueAt || ''" @change="editDue"/></label></div><div class="priority"><span>Prioridad</span><div><button v-for="(label,value) in ['Baja','Normal','Alta']" :key="value" :class="['priority-btn',`p-${value}`,{active:task.priority===value}]" @click="emit('priority',task.id,value)">{{label}}</button></div></div><button class="delete" aria-label="Eliminar recordatorio" @click="emit('remove',task.id)">×</button></article></template>
<style scoped>
.task-card{align-items:center;background:rgba(21,29,33,.95);border:1px solid var(--line);border-radius:8px;display:flex;gap:1rem;margin:.7rem auto;max-width:980px;padding:1rem 1.2rem;transition:.2s}.task-card:hover{border-color:rgba(24,211,154,.4);transform:translateY(-1px)}.task-card.completed{opacity:.65}.check{background:transparent;border:1px solid #587076;border-radius:5px;color:#071318;height:1.3rem;width:1.3rem}.check.active{background:var(--teal);border-color:var(--teal)}.task-main{flex:1}.task-main h3{font-size:.9rem;margin:0 0 .25rem}.completed h3{text-decoration:line-through}.task-main p,.priority span{color:var(--muted);font-size:.68rem;margin:0}.due-date{align-items:center;color:var(--muted);display:flex;font-size:.65rem;gap:.4rem;margin-top:.5rem}.due-date input{background:#0d1317;border:1px solid var(--line);border-radius:4px;color:var(--muted);font-size:.62rem;padding:.3rem}.due-date input:focus{border-color:var(--teal);outline:0}.priority{min-width:190px}.priority span{display:block;margin-bottom:.35rem}.priority-btn{background:transparent;border:1px solid var(--line);border-radius:4px;color:var(--muted);font-size:.62rem;margin-right:.3rem;padding:.3rem .45rem}.priority-btn.active{color:var(--text)}.priority-btn.p-0.active{border-color:#67a7cb;color:#67c8ff}.priority-btn.p-1.active{border-color:var(--teal);color:var(--teal)}.priority-btn.p-2.active{border-color:var(--red);color:var(--red)}.delete{background:transparent;border:0;color:var(--muted);font-size:1.4rem}.delete:hover{color:var(--red)}@media(max-width:600px){.task-card{align-items:flex-start;flex-wrap:wrap}.priority{margin-left:2.3rem;min-width:0;width:calc(100% - 2.3rem)}.due-date{align-items:flex-start;flex-direction:column}}
</style>
